      SUBROUTINE RCOUTCC     DIRECTS PRINTING OF TRANSFER MATRICESCC ----------------------------------------------------------------------      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'IOUNIT.CIN'CC     LOCAL VARIABLESC      REAL            ALONGC----------------------------------------------------------------------------CC     ACCUMULATED LENGTHC      IF (LCPR) GO TO 10      ALONG = LC/UFLOOR(1)      IF (.NOT. TERSE) WRITE (NOUT,1007) ALONG, XFLOOR(1) 1007 FORMAT (1H ,8X,F10.3,1X,A4)CC     DETERMINE TRANSFER MATRIXC   10 IF (NORD3 .GE. 1) CALL RCALC      IF (TYPE .EQ. 13 .AND. CDB .EQ. 4 .AND. RAT)     1    GO TO 200CC     PRINT FIRST ORDER TRANSFER MATRIXC  110 CALL RCOUT1CC     PRINT SECOND ORDER TRANSFER MATRIXC  200 IF (NORD3 .GE. 2 .AND.     1   (CDB .EQ. 4 .OR. CDB .EQ. -4 .OR. CDB .EQ. 24 .OR. TERSE))     2    CALL RCOUT2      IF (NORD3 .GE. 3 .AND.      1   (CDB .EQ. 4 .OR. CDB .EQ. -4 .OR. CDB .EQ. 24))     1    CALL RCOUT3C  400 LCPR = .TRUE.      RETURN      END